def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    solid_rows = [r for r in range(h) if all(v == grid[r][0] for v in grid[r])]
    solid_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    for r in solid_rows:
        out[r] = [2] * w
    for c in solid_cols:
        for r in range(h):
            out[r][c] = 2
    return out
